begin;
create extension if not exists pgcrypto;
create table if not exists public.ecommerce_products(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,description text not null default '',category text not null default 'General',price numeric(12,2) not null check(price>=0),compare_at_price numeric(12,2),image_jpg text,stock integer not null default 0 check(stock>=0),is_featured boolean not null default false,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.ecommerce_admins(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create table if not exists public.ecommerce_orders(id uuid primary key default gen_random_uuid(),order_number text unique not null default('NV-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),user_id uuid not null references auth.users(id) on delete restrict,customer_name text not null,phone text not null,shipping_address text not null,subtotal numeric(12,2) not null,shipping_fee numeric(12,2) not null default 0,total numeric(12,2) not null,status text not null default 'pending' check(status in('pending','confirmed','processing','shipped','delivered','cancelled')),payment_status text not null default 'created' check(payment_status in('created','verified','captured','failed','refunded')),razorpay_order_id text,razorpay_payment_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.ecommerce_order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.ecommerce_orders(id) on delete cascade,product_id uuid references public.ecommerce_products(id) on delete set null,product_name text not null,quantity integer not null,unit_price numeric(12,2) not null,line_total numeric(12,2) not null,created_at timestamptz not null default now());
create index if not exists e_products_active_idx on public.ecommerce_products(is_active,category);create index if not exists e_orders_user_idx on public.ecommerce_orders(user_id,created_at desc);
create or replace function public.ecommerce_is_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.ecommerce_admins where user_id=(select auth.uid()))$$;
revoke all on function public.ecommerce_is_admin() from public;grant execute on function public.ecommerce_is_admin() to authenticated;
create or replace function public.touch_ecommerce_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end$$;
drop trigger if exists e_products_updated on public.ecommerce_products;create trigger e_products_updated before update on public.ecommerce_products for each row execute function public.touch_ecommerce_updated_at();
drop trigger if exists e_orders_updated on public.ecommerce_orders;create trigger e_orders_updated before update on public.ecommerce_orders for each row execute function public.touch_ecommerce_updated_at();

alter table public.ecommerce_products enable row level security;alter table public.ecommerce_admins enable row level security;alter table public.ecommerce_orders enable row level security;alter table public.ecommerce_order_items enable row level security;
drop policy if exists products_public_read on public.ecommerce_products;create policy products_public_read on public.ecommerce_products for select to anon,authenticated using(is_active=true or public.ecommerce_is_admin());
drop policy if exists products_admin_all on public.ecommerce_products;create policy products_admin_all on public.ecommerce_products for all to authenticated using(public.ecommerce_is_admin()) with check(public.ecommerce_is_admin());
drop policy if exists admins_self on public.ecommerce_admins;create policy admins_self on public.ecommerce_admins for select to authenticated using(user_id=(select auth.uid()) or public.ecommerce_is_admin());
drop policy if exists orders_customer_read on public.ecommerce_orders;create policy orders_customer_read on public.ecommerce_orders for select to authenticated using(user_id=(select auth.uid()) or public.ecommerce_is_admin());
drop policy if exists orders_admin_update on public.ecommerce_orders;create policy orders_admin_update on public.ecommerce_orders for update to authenticated using(public.ecommerce_is_admin()) with check(public.ecommerce_is_admin());
drop policy if exists items_customer_read on public.ecommerce_order_items;create policy items_customer_read on public.ecommerce_order_items for select to authenticated using(exists(select 1 from public.ecommerce_orders o where o.id=order_id and(o.user_id=(select auth.uid()) or public.ecommerce_is_admin())));

grant select on public.ecommerce_products to anon,authenticated;grant insert,update,delete on public.ecommerce_products to authenticated;grant select on public.ecommerce_admins to authenticated;grant select,update on public.ecommerce_orders to authenticated;grant select on public.ecommerce_order_items to authenticated;

create or replace function public.finalize_ecommerce_payment(p_order_id uuid,p_payment_id text) returns public.ecommerce_orders language plpgsql security definer set search_path='' as $$
declare v_order public.ecommerce_orders%rowtype; v_item record; begin select * into v_order from public.ecommerce_orders where id=p_order_id for update; if not found then raise exception 'Order not found.'; end if; if v_order.payment_status in ('verified','captured') then return v_order; end if; for v_item in select product_id,quantity from public.ecommerce_order_items where order_id=p_order_id loop if v_item.product_id is not null then update public.ecommerce_products set stock=stock-v_item.quantity where id=v_item.product_id and stock>=v_item.quantity; if not found then raise exception 'Stock is no longer available for one of the paid items.'; end if; end if; end loop; update public.ecommerce_orders set payment_status='verified',status='confirmed',razorpay_payment_id=p_payment_id where id=p_order_id returning * into v_order; return v_order; end; $$;
revoke all on function public.finalize_ecommerce_payment(uuid,text) from public;grant execute on function public.finalize_ecommerce_payment(uuid,text) to service_role;

insert into public.ecommerce_products(name,slug,description,category,price,compare_at_price,image_jpg,stock,is_featured,is_active) values
