('Classic Smartwatch','classic-smartwatch','A clean everyday watch with activity tracking and a bright edge-to-edge display.','Electronics',5999,6999,'https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=1000&q=85',18,true,true),
('Minimal Shoulder Bag','minimal-shoulder-bag','Structured recycled fabric with a soft finish and enough space for everyday essentials.','Lifestyle',3299,3999,'https://images.unsplash.com/photo-1584917865442-de89df76afd3?auto=format&fit=crop&w=1000&q=85',14,true,true),
('Wireless Studio Headphones','wireless-studio-headphones','Balanced sound, soft cushions and long battery life for focused listening.','Electronics',7999,9999,'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=1000&q=85',9,true,true),
('Organic Oversized Shirt','organic-oversized-shirt','Relaxed cotton shirt with a clean drape for workdays and weekends.','Fashion',2499,2999,'https://images.unsplash.com/photo-1605763240000-7e93b172d754?auto=format&fit=crop&w=1000&q=85',30,false,true),
('Hydrating Face Serum','hydrating-face-serum','Lightweight daily serum designed for a simple, comfortable skincare routine.','Beauty',1299,null,'https://images.unsplash.com/photo-1620916566398-39f1143ab7ba?auto=format&fit=crop&w=1000&q=85',22,false,true)
on conflict(slug) do update set price=excluded.price,compare_at_price=excluded.compare_at_price,image_jpg=excluded.image_jpg,is_active=true;
commit;
